-- 0008：修正已经保存的摘要里没有解码的 HTML 实体（例如 We&#x27;re → We're）和零宽占位字符
-- 只有 HTML、没有纯文本的邮件，之前的 HTML 转文字只认识少数几种实体
UPDATE messages SET snippet = TRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(snippet, '&#x27;', ''''), '&#X27;', ''''), '&#39;', ''''), '&apos;', ''''), '&quot;', '"'), '&#34;', '"'), '&rsquo;', '’'), '&#8217;', '’'), '&#x2019;', '’'), '&lsquo;', '‘'), '&#8216;', '‘'), '&ldquo;', '“'), '&#8220;', '“'), '&rdquo;', '”'), '&#8221;', '”'), '&mdash;', '—'), '&#8212;', '—'), '&ndash;', '–'), '&#8211;', '–'), '&hellip;', '…'), '&#8230;', '…'), '&nbsp;', ' '), '&#160;', ' '), '&#xa0;', ' '), '&#xA0;', ' '), '&zwnj;', ''), '&#8204;', ''), '&#x200c;', ''), '&zwj;', ''), '&shy;', ''), '&lt;', '<'), '&gt;', '>'), '&amp;', '&'), char(8203), ''), char(8204), ''), char(8205), ''), char(8288), ''), char(65279), ''), char(847), ''), char(173), '')) WHERE snippet LIKE '%&%;%' OR instr(snippet, char(8203)) > 0 OR instr(snippet, char(8204)) > 0 OR instr(snippet, char(8205)) > 0 OR instr(snippet, char(8288)) > 0 OR instr(snippet, char(65279)) > 0 OR instr(snippet, char(847)) > 0 OR instr(snippet, char(173)) > 0;
